package com.tekwatt.invoice.service;import com.tekwatt.invoice.dto.*;import com.tekwatt.invoice.entity.*;import com.tekwatt.invoice.repository.InvoiceRepository;import java.math.BigDecimal;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class InvoiceService{private final InvoiceRepository repo;public InvoiceService(InvoiceRepository r){repo=r;}public InvoiceResponse create(CreateInvoiceRequest r){if(repo.existsByBillId(r.billId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Bill is already invoiced");if(r.dueDate().isBefore(r.issueDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Due date cannot precede issue date");if(r.subtotal().add(r.taxAmount()).compareTo(r.totalAmount())!=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Total must equal subtotal plus tax");String n="INV-"+DateTimeFormatter.ofPattern("yyyyMMddHHmmss").withZone(ZoneOffset.UTC).format(Instant.now())+"-"+UUID.randomUUID().toString().substring(0,6).toUpperCase();return InvoiceResponse.from(repo.save(new Invoice(r.tenantId(),r.userId(),r.billId(),n,r.customerName(),r.customerEmail(),r.billingAddress(),r.taxRegistrationNumber(),r.subtotal(),r.taxAmount(),r.totalAmount(),r.currency(),r.issueDate(),r.dueDate())));}@Transactional(readOnly=true)public InvoiceResponse get(UUID id){Invoice i=find(id);i.markOverdue();return InvoiceResponse.from(i);}@Transactional(readOnly=true)public List<InvoiceResponse>list(UUID tenantId){return repo.findAllByTenantIdOrderByCreatedAtDesc(tenantId).stream().map(InvoiceResponse::from).toList();}public InvoiceResponse issue(UUID id){Invoice i=find(id);if(i.getStatus()!=InvoiceStatus.DRAFT)conflict();i.issue();return InvoiceResponse.from(i);}public InvoiceResponse pay(UUID id){Invoice i=find(id);i.markOverdue();if(i.getStatus()!=InvoiceStatus.ISSUED&&i.getStatus()!=InvoiceStatus.OVERDUE)conflict();i.pay();return InvoiceResponse.from(i);}public InvoiceResponse voidInvoice(UUID id){Invoice i=find(id);if(i.getStatus()==InvoiceStatus.PAID||i.getStatus()==InvoiceStatus.VOID)conflict();i.voidInvoice();return InvoiceResponse.from(i);}private void conflict(){throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid invoice status transition");}private Invoice find(UUID id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice not found"));}}
